// The F3 performance panel (Slice 11, after the recomp's "Performance panel"):
// the frame rate, the frames shown (real and generated), the render and
// output size, CPU and GPU stage times, video memory and resident world
// cells, HDR and V-sync, and a build line to quote in a bug report. The
// numbers are gathered by FrameStats (plain C++, no Vulkan, so it is
// tested) and the panel is drawn with the UI layer (ui.h), so it sits above
// the HUD and is never generated by frame generation.
#pragma once

#include <cstdint>
#include <deque>
#include <string>
#include <utility>
#include <vector>

#include "ui.h"

namespace carview {

// Rolling frame statistics: call frame() once per presented frame.
class FrameStats {
 public:
  explicit FrameStats(double window_seconds = 1.0, size_t keep = 4096) : window_(window_seconds), keep_(keep) {}
  // `now_sec`: any monotonic clock, in seconds.
  void frame(double now_sec);
  // A frame the GPU or the upscaler's frame generation made between two real ones.
  void generated(uint32_t n = 1) { generated_total_ += n, generated_recent_.push_back({last_, n}); }
  // Real frames per second over the last `window` seconds.
  double fps() const;
  double generated_fps() const;
  // Over the kept frame times (ms between presented frames).
  double ms_avg() const;
  double ms_percentile(double q) const;  // 0..1
  double ms_max() const;
  size_t frames() const { return total_; }
  uint64_t generated_total() const { return generated_total_; }
  // "frames N, fps X, frame ms avg/p50/p95/p99/max" for logs and benches.
  std::string summary() const;
  void reset();

 private:
  double window_;
  size_t keep_;
  double last_ = -1.0;
  size_t total_ = 0;
  uint64_t generated_total_ = 0;
  std::deque<double> stamps_;                           // presented-frame times inside the window
  std::deque<std::pair<double, uint32_t>> generated_recent_;
  std::deque<double> deltas_;                           // ms between frames, newest last
};

// What the panel shows. Filled by the caller from the renderer and the loop.
struct PerfInfo {
  double fps = 0.0, generated_fps = 0.0;
  uint32_t render_w = 0, render_h = 0, output_w = 0, output_h = 0;
  double cpu_ms = -1.0;                                   // the loop's CPU time per frame
  double gpu_ms = -1.0;                                   // negative: no timestamps on this queue
  std::vector<std::pair<std::string, double>> gpu_stages; // marked GPU stages, ms
  uint64_t vram_used = 0, vram_budget = 0;                // bytes of device-local memory
  uint32_t resident_cells = 0, resident_draws = 0;        // the GPU-resident scenery
  uint32_t draws_drawn = 0, draws_culled = 0;             // the world's draws this frame
  bool hdr = false;
  std::string vsync;     // "FIFO", "MAILBOX", "IMMEDIATE"
  std::string upscaler;  // "BILINEAR", "FSR 1 (UNAVAILABLE -> FSR 1)", ...
  std::string frame_generation;  // "OFF", "FSR 3", ...
  std::string device;
  std::string build;     // "shift-engine <commit> <date>"
};

// The panel's text, one line per entry (so tests can read it).
std::vector<std::string> perf_overlay_lines(const PerfInfo& info);

// Draws the panel at the top left of a `width` x `height` screen. `scale`
// multiplies its size (the recomp's debug_overlay_scale), and it also grows
// with the window (a 1080-line screen draws it at 1x).
void build_perf_overlay(ui::List& list, const PerfInfo& info, float width, float height, float scale = 1.0f);

// "12.3 MiB" style sizes for the panel.
std::string format_bytes(uint64_t bytes);

}  // namespace carview
